package org.sleepwell.app;
import javax.net.ssl.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.util.function.BooleanSupplier;import org.json.*;
/** GET only. Hub snapshots are on-change states, never fresh hardware measurements. */
final class PirHttp {
 static final java.util.Set<String> QUALITY=java.util.Set.of("HUB_STATE","HUB_UNKNOWN","UNSUPPORTED","UNAVAILABLE","CLOCK_CHANGED");static final Semaphore NETWORK=new Semaphore(1);private final AtomicReference<HttpsURLConnection> active=new AtomicReference<>();private volatile boolean cancelled;
 static final class Reading {final Integer state;final String quality,deviceClass;final Long age;final long latency;Reading(Integer state,String quality,String deviceClass,Long age,long latency){this.state=state;this.quality=quality;this.deviceClass=deviceClass;this.age=age;this.latency=latency;}}
 Reading read(PirConfig config,BooleanSupplier live)throws Exception{config.validate();if(!NETWORK.tryAcquire())throw new IOException("Another PIR read is still closing.");long began=android.os.SystemClock.elapsedRealtime();HttpsURLConnection connection=null;try{check(live);connection=(HttpsURLConnection)new URL(config.base()+"/api/states/"+config.entity).openConnection();active.set(connection);connection.setConnectTimeout(4000);connection.setReadTimeout(4000);connection.setInstanceFollowRedirects(false);connection.setUseCaches(false);connection.setRequestMethod("GET");connection.setRequestProperty("Authorization","Bearer "+config.token);connection.setRequestProperty("Accept","application/json");connection.setRequestProperty("Cache-Control","no-cache");int code=connection.getResponseCode();check(live);if(code!=200)throw new IOException(code==401||code==403?"Home Assistant rejected the PIR token.":code==404?"The PIR entity was not found.":"Home Assistant PIR read failed.");String text;try(InputStream input=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] block=new byte[2048];int total=0;for(int n;(n=input.read(block))!=-1;){check(live);if(android.os.SystemClock.elapsedRealtime()-began>8000||((total+=n)>65536))throw new IOException("PIR response exceeded the read limit.");out.write(block,0,n);}text=new String(out.toByteArray(),StandardCharsets.UTF_8);}check(live);long latency=android.os.SystemClock.elapsedRealtime()-began;if(latency>8000)throw new IOException("PIR read timed out.");JSONObject j=new JSONObject(text);if(!config.entity.equals(j.getString("entity_id")))throw new IOException("PIR response identity did not match.");String device=j.getJSONObject("attributes").optString("device_class","");if(!java.util.Set.of("motion","occupancy").contains(device))return new Reading(null,"UNSUPPORTED",device,null,latency);String value=j.getString("state");Integer state=value.equals("on")?1:value.equals("off")?0:null;Long age=null;try{long changed=Instant.parse(j.getString("last_updated")).toEpochMilli(),difference=System.currentTimeMillis()-changed;if(difference>=0&&difference<=315576000000L)age=difference;}catch(Exception ignored){}return new Reading(state,state==null?"HUB_UNKNOWN":"HUB_STATE",device,age,latency);
 }catch(SSLException tls){throw new IOException("PIR HTTPS certificate verification failed.");}catch(SocketTimeoutException timeout){throw new IOException("PIR read timed out.");}finally{if(connection!=null){active.compareAndSet(connection,null);connection.disconnect();}NETWORK.release();}}
 private void check(BooleanSupplier live)throws IOException{if(cancelled||!live.getAsBoolean()||Thread.currentThread().isInterrupted())throw new IOException("PIR read cancelled.");}
 void cancel(){cancelled=true;HttpsURLConnection c=active.get();if(c!=null)CANCEL.execute(c::disconnect);}
 private static final Executor CANCEL=new ThreadPoolExecutor(0,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),r->new Thread(r,"pir-cancel"),new ThreadPoolExecutor.DiscardPolicy());
}
